WITH CANDIDATES AS 
	( -- This CTE retrieves the candidate information
		SELECT DISTINCT
			  DVO_SRC1.CANDIDATE_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC1.CANDIDATE_BK AS CANDIDATE_BK
			, SAT_SRC1_1_1._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
			, SAT_SRC1_1_1.CANDIDATE_FULL_NAME AS CANDIDATE_FULL_NAME
        FROM {{ source('eli_dv_bv', 'hub_candidate') }} DVO_SRC1
		JOIN {{ ref('sat_ssc_candidate_bvv_curr') }} SAT_SRC1_1_1 ON  DVO_SRC1.CANDIDATE_HKEY = SAT_SRC1_1_1.CANDIDATE_HKEY
	)
,PLACEMENTS AS 
    ( -- This CTE retrieves the placement information
        SELECT DISTINCT
              DVO_SRC2.PLACEMENT_HKEY AS BASE_OBJECT_H_KEY
            , DVO_SRC2.PLACEMENT_BK AS PLACEMENT_BK
            , SAT_SRC1_1_2._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
            , SAT_SRC1_1_2.ACTUAL_END_DATE_DATETIME__C AS ACTUAL_END_DATE
            , SAT_SRC1_1_2.AVAILABLE_FOR_REASSIGNMENT AS AVAILABLE_FOR_REASSIGNMENT
            , SAT_SRC1_1_2.DW_BH_ID__C AS DW_BH_ID
            , SAT_SRC1_1_2.CLOSING_REPORT_NUMBER AS CLOSING_REPORT_NUMBER
            , SAT_SRC1_1_2.CONTRACT_TYPE AS CONTRACT_TYPE
            , SAT_SRC1_1_2.CONTRACTOR_TYPE AS CONTRACTOR_TYPE
            , SAT_SRC1_1_2.DIVISION AS DIVISION
            , SAT_SRC1_1_2.DOMAIN AS DOMAIN
            , SAT_SRC1_1_2.END_ASSIGNMENT_COMMENTS AS END_ASSIGNMENT_COMMENTS
            , SAT_SRC1_1_2.END_ASSIGNMENT_REASON AS END_ASSIGNMENT_REASON
            , SAT_SRC1_1_2.ESTIMATED_END_DATE AS ESTIMATED_END_DATE
            , SAT_SRC1_1_2.HIRING_MANAGER AS HIRING_MANAGER
            , SAT_SRC1_1_2.IMMIGRATION_SPONSORSHIP AS IMMIGRATION_SPONSORSHIP
            , SAT_SRC1_1_2.IS_WORK_FROM_HOME AS IS_WORK_FROM_HOME
            , SAT_SRC1_1_2.PLACEMENT_ELI_LEGACY_SYSTEM_ID AS PLACEMENT_ELI_LEGACY_SYSTEM_ID
            , SAT_SRC1_1_2.ONBOARDING_STATUS AS ONBOARDING_STATUS
            , SAT_SRC1_1_2.PAYMENT_TERMS AS PAYMENT_TERMS
            , SAT_SRC1_1_2.SEGMENT AS SEGMENT
            , SAT_SRC1_1_2.START_DATE AS START_DATE
            , SAT_SRC1_1_2.PLACEMENT_STATUS AS PLACEMENT_STATUS
            , SAT_SRC1_1_2.PLACEMENT_VIA_SF_LEGACY_ID AS PLACEMENT_VIA_SF_LEGACY_ID
            , SAT_SRC1_1_2.ELI_WORK_LOCATION__C AS WORK_LOCATION
			, SAT_SRC1_1_2.ELI_ACCOUNT_LOCATION__C AS ACCOUNT_LOCATION
            , SAT_SRC1_1_2.CONSULTING_REVENUE__C AS CONSULTING_REVENUE
        FROM {{ source('eli_dv_bv', 'hub_placement') }} DVO_SRC2
        JOIN {{ ref('sat_bh4sf_placement_bvv_curr') }} SAT_SRC1_1_2 ON DVO_SRC2.PLACEMENT_HKEY = SAT_SRC1_1_2.PLACEMENT_HKEY
    ) 
,COMPANIES AS 
	( -- This CTE retrieves the company information
		SELECT DISTINCT
			  DVO_SRC3.COMPANY_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC3.COMPANY_BK AS COMPANY_BK
			, SAT_SRC1_1_3._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
			, SAT_SRC1_1_3.ACCOUNT_NAME AS ACCOUNT_NAME
		FROM {{ source('eli_dv_bv', 'hub_company') }} DVO_SRC3
		INNER JOIN {{ ref('sat_ssc_company_bvv_curr') }} SAT_SRC1_1_3 ON  DVO_SRC3.COMPANY_HKEY = SAT_SRC1_1_3.COMPANY_HKEY
	)
,ASSIGNED_RECRUITERS AS 
    (
        SELECT DISTINCT
			  DVO_SRC4.USER_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC4.USER_BK AS USER_BK
			, SAT_SRC1_1_4._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
			, SAT_SRC1_1_4.NAME AS ASSIGNED_RECRUITER
        FROM {{ source('eli_dv_bv', 'hub_user') }} DVO_SRC4
		JOIN {{ ref('sat_ssc_user_bvv_curr') }} SAT_SRC1_1_4 ON  DVO_SRC4.USER_HKEY = SAT_SRC1_1_4.USER_HKEY
    )
, JOB_OWNERS AS 
	(
        SELECT DISTINCT
			  DVO_SRC5.USER_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC5.USER_BK AS USER_BK
			, SAT_SRC1_1_5._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
			, SAT_SRC1_1_5.NAME AS PLACEMENT_JOB_OWNER
        FROM {{ source('eli_dv_bv', 'hub_user') }} DVO_SRC5
		JOIN {{ ref('sat_ssc_user_bvv_curr') }} SAT_SRC1_1_5 ON  DVO_SRC5.USER_HKEY = SAT_SRC1_1_5.USER_HKEY
    )
, CONTACTS AS 
	(
        SELECT DISTINCT
			  DVO_SRC6.CONTACT_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC6.CONTACT_BK AS CONTACT_BK
			, SAT_SRC1_1_6._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
			, SAT_SRC1_1_6.CONTACT_NAME AS CONTACT_NAME
        FROM {{ source('eli_dv_bv', 'hub_contact') }} DVO_SRC6
		JOIN {{ ref('sat_ssc_contact_bvv_curr') }} SAT_SRC1_1_6 ON  DVO_SRC6.CONTACT_HKEY = SAT_SRC1_1_6.CONTACT_HKEY
    )
, POSITIONS AS 
	(
        SELECT DISTINCT
			  DVO_SRC7.POSITION_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC7.POSITION_BK AS POSITION_BK
			, SAT_SRC1_1_7._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
			, SAT_SRC1_1_7.JOB_NAME AS JOB_NAME
        FROM {{ source('eli_dv_bv', 'hub_position') }} DVO_SRC7
		JOIN {{ ref('sat_bh4sf_position_bvv_curr') }} SAT_SRC1_1_7 ON  DVO_SRC7.POSITION_HKEY = SAT_SRC1_1_7.POSITION_HKEY
    )
, MATCHES AS 
	(
        SELECT DISTINCT
			  DVO_SRC8.MATCH_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC8.MATCH_BK AS MATCH_BK
			, SAT_SRC1_1_8._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
			, SAT_SRC1_1_8.NAME AS MATCH_NAME
        FROM {{ source('eli_dv_bv', 'hub_match') }} DVO_SRC8
		JOIN {{ ref('sat_bh4sf_match_bvv_curr') }} SAT_SRC1_1_8 ON  DVO_SRC8.MATCH_HKEY = SAT_SRC1_1_8.MATCH_HKEY
    )
, TIMESHEET_APPROVERS AS 
	(
        SELECT DISTINCT
			  DVO_SRC9.CONTACT_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC9.CONTACT_BK AS CONTACT_BK
			, SAT_SRC1_1_9._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
			, SAT_SRC1_1_9.CONTACT_NAME AS TIMESHEET_APPROVER
        FROM {{ source('eli_dv_bv', 'hub_contact') }} DVO_SRC9
		JOIN {{ ref('sat_ssc_contact_bvv_curr') }} SAT_SRC1_1_9 ON  DVO_SRC9.CONTACT_HKEY = SAT_SRC1_1_9.CONTACT_HKEY
    )
, RECORD_TYPES AS 
    (
        SELECT DISTINCT
			  DVO_SRC18.RECORDTYPE_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC18.ID_BK AS ID_BK
			, SAT_SRC1_1_18._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
			, SAT_SRC1_1_18.NAME AS RECORD_TYPE
        FROM {{ source('eli_dv_bv', 'hub_recordtype') }} DVO_SRC18
		JOIN {{ ref('sat_ssc_recordtype_bvv_curr') }} SAT_SRC1_1_18 ON  DVO_SRC18.RECORDTYPE_HKEY = SAT_SRC1_1_18.RECORDTYPE_HKEY
    )
, PLACEMENT_COMPANY AS 
	( 
		SELECT DISTINCT
			  DVO_SRC10.PLACEMENT_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC10.LNA_PLACEMENT_COMPANY_HKEY AS BASE_OBJECT_L_H_KEY
			, DVO_SRC10.COMPANY_HKEY AS BASE_OBJECT_F_H_KEY
            , ROW_NUMBER() OVER (
				PARTITION BY DVO_SRC10.PLACEMENT_HKEY -- Partition by match to get the latest company
				ORDER BY SAT_SRC1_1_10._AIRBYTE_EXTRACTED_AT DESC -- Order by snapshot timestamp to get the latest
			) AS RN
			, SAT_SRC1_1_10._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
		FROM {{ source('eli_dv_bv', 'lna_placement_company') }} DVO_SRC10
		INNER JOIN {{ ref('view_las_bh4sf_placement_company_bvv_curr') }} SAT_SRC1_1_10 ON  DVO_SRC10.LNA_PLACEMENT_COMPANY_HKEY = SAT_SRC1_1_10.LNA_PLACEMENT_COMPANY_HKEY
    )    
, PLACEMENT_AR AS 
	( 
		SELECT DISTINCT
			  DVO_SRC11.PLACEMENT_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC11.LNA_PLACEMENT_USER_ASSIGNEDRECRUITERC_HKEY AS BASE_OBJECT_L_H_KEY
			, DVO_SRC11.USER_ASSIGNEDRECRUITERC_HKEY AS BASE_OBJECT_F_H_KEY
            , ROW_NUMBER() OVER (
				PARTITION BY DVO_SRC11.PLACEMENT_HKEY -- Partition by match to get the latest company
				ORDER BY SAT_SRC1_1_11._AIRBYTE_EXTRACTED_AT DESC -- Order by snapshot timestamp to get the latest
			) AS RN
			, SAT_SRC1_1_11._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
	    FROM {{ source('eli_dv_bv', 'lna_placement_user_assignedrecruiterc') }} DVO_SRC11
		INNER JOIN {{ ref('view_las_bh4sf_placement_user_assignedrecruiterc_bvv_curr') }} SAT_SRC1_1_11 ON  DVO_SRC11.LNA_PLACEMENT_USER_ASSIGNEDRECRUITERC_HKEY = SAT_SRC1_1_11.LNA_PLACEMENT_USER_ASSIGNEDRECRUITERC_HKEY
    )
, PLACEMENT_JOBOWNER AS 
	( 
		SELECT DISTINCT
			  DVO_SRC12.PLACEMENT_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC12.LNA_PLACEMENT_USER_PLACEMENTJOBOWNERC_HKEY AS BASE_OBJECT_L_H_KEY
			, DVO_SRC12.USER_PLACEMENTJOBOWNERC_HKEY AS BASE_OBJECT_F_H_KEY
            , ROW_NUMBER() OVER (
				PARTITION BY DVO_SRC12.PLACEMENT_HKEY -- Partition by match to get the latest company
				ORDER BY SAT_SRC1_1_12._AIRBYTE_EXTRACTED_AT DESC -- Order by snapshot timestamp to get the latest
			) AS RN
			, SAT_SRC1_1_12._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
	    FROM {{ source('eli_dv_bv', 'lna_placement_user_placementjobownerc') }} DVO_SRC12
		INNER JOIN {{ ref('view_las_bh4sf_placement_user_placementjobownerc_bvv_curr') }} SAT_SRC1_1_12 ON  DVO_SRC12.LNA_PLACEMENT_USER_PLACEMENTJOBOWNERC_HKEY = SAT_SRC1_1_12.LNA_PLACEMENT_USER_PLACEMENTJOBOWNERC_HKEY
    )
, PLACEMENT_BILLINGCONTACT AS 
	( 
		SELECT DISTINCT
			  DVO_SRC13.PLACEMENT_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC13.LNA_PLACEMENT_CONTACT_ELIBILLINGCONTACTC_HKEY AS BASE_OBJECT_L_H_KEY
			, DVO_SRC13.CONTACT_ELIBILLINGCONTACTC_HKEY AS BASE_OBJECT_F_H_KEY
            , ROW_NUMBER() OVER (
				PARTITION BY DVO_SRC13.PLACEMENT_HKEY -- Partition by match to get the latest company
				ORDER BY SAT_SRC1_1_13._AIRBYTE_EXTRACTED_AT DESC -- Order by snapshot timestamp to get the latest
			) AS RN
			, SAT_SRC1_1_13._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
	    FROM {{ source('eli_dv_bv', 'lna_placement_contact_elibillingcontactc') }} DVO_SRC13
		INNER JOIN {{ ref('view_las_bh4sf_placement_contact_elibillingcontactc_bvv_curr') }} SAT_SRC1_1_13 ON  DVO_SRC13.LNA_PLACEMENT_CONTACT_ELIBILLINGCONTACTC_HKEY = SAT_SRC1_1_13.LNA_PLACEMENT_CONTACT_ELIBILLINGCONTACTC_HKEY
    ) 
, PLACEMENT_TIMESHEETAPPROVER AS 
	( 
		SELECT DISTINCT
			  DVO_SRC14.PLACEMENT_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC14.LNA_PLACEMENT_CONTACT_TR1TIMESHEETAPPROVERC_HKEY AS BASE_OBJECT_L_H_KEY
			, DVO_SRC14.CONTACT_TR1TIMESHEETAPPROVERC_HKEY AS BASE_OBJECT_F_H_KEY
            , ROW_NUMBER() OVER (
				PARTITION BY DVO_SRC14.PLACEMENT_HKEY -- Partition by match to get the latest company
				ORDER BY SAT_SRC1_1_14._AIRBYTE_EXTRACTED_AT DESC -- Order by snapshot timestamp to get the latest
			) AS RN
			, SAT_SRC1_1_14._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
	    FROM {{ source('eli_dv_bv', 'lna_placement_contact_tr1timesheetapproverc') }} DVO_SRC14
		INNER JOIN {{ ref('view_las_bh4sf_placement_contact_tr1timesheetapproverc_bvv_curr') }} SAT_SRC1_1_14 ON  DVO_SRC14.LNA_PLACEMENT_CONTACT_TR1TIMESHEETAPPROVERC_HKEY = SAT_SRC1_1_14.LNA_PLACEMENT_CONTACT_TR1TIMESHEETAPPROVERC_HKEY
    )
, PLACEMENT_MATCH AS 
	( 
		SELECT DISTINCT
			  DVO_SRC15.PLACEMENT_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC15.LNK_PLACEMENT_MATCH_HKEY AS BASE_OBJECT_L_H_KEY
			, DVO_SRC15.MATCH_HKEY AS BASE_OBJECT_F_H_KEY
            , ROW_NUMBER() OVER (
				PARTITION BY DVO_SRC15.PLACEMENT_HKEY -- Partition by match to get the latest company
				ORDER BY SAT_SRC1_1_15._AIRBYTE_EXTRACTED_AT DESC -- Order by snapshot timestamp to get the latest
			) AS RN
			, SAT_SRC1_1_15._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
	    FROM {{ source('eli_dv_bv', 'lnk_placement_match') }} DVO_SRC15
		INNER JOIN {{ ref('lks_bh4sf_placement_match_bvv_curr') }} SAT_SRC1_1_15 ON  DVO_SRC15.LNK_PLACEMENT_MATCH_HKEY = SAT_SRC1_1_15.LNK_PLACEMENT_MATCH_HKEY
    ) 
, PLACEMENT_CANDIDATE AS 
	( 
		SELECT DISTINCT
			  DVO_SRC16.PLACEMENT_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC16.LNA_PLACEMENT_CANDIDATE_HKEY AS BASE_OBJECT_L_H_KEY
			, DVO_SRC16.CANDIDATE_HKEY AS BASE_OBJECT_F_H_KEY
            , ROW_NUMBER() OVER (
				PARTITION BY DVO_SRC16.PLACEMENT_HKEY -- Partition by match to get the latest company
				ORDER BY SAT_SRC1_1_16._AIRBYTE_EXTRACTED_AT DESC -- Order by snapshot timestamp to get the latest
			) AS RN
			, SAT_SRC1_1_16._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
	    FROM {{ source('eli_dv_bv', 'lna_placement_candidate') }} DVO_SRC16
		INNER JOIN {{ ref('view_las_bh4sf_placement_candidate_bvv_curr') }} SAT_SRC1_1_16 ON  DVO_SRC16.LNA_PLACEMENT_CANDIDATE_HKEY = SAT_SRC1_1_16.LNA_PLACEMENT_CANDIDATE_HKEY
    )
, PLACEMENT_POSITION AS 
	( 
		SELECT DISTINCT
			  DVO_SRC17.PLACEMENT_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC17.LNK_PLACEMENT_POSITION_HKEY AS BASE_OBJECT_L_H_KEY
			, DVO_SRC17.POSITION_HKEY AS BASE_OBJECT_F_H_KEY
            , ROW_NUMBER() OVER (
				PARTITION BY DVO_SRC17.PLACEMENT_HKEY -- Partition by match to get the latest company
				ORDER BY SAT_SRC1_1_17._AIRBYTE_EXTRACTED_AT DESC -- Order by snapshot timestamp to get the latest
			) AS RN
			, SAT_SRC1_1_17._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
	    FROM {{ source('eli_dv_bv', 'lnk_placement_position') }} DVO_SRC17
		INNER JOIN {{ ref('lks_bh4sf_placement_position_bvv_curr') }} SAT_SRC1_1_17 ON  DVO_SRC17.LNK_PLACEMENT_POSITION_HKEY = SAT_SRC1_1_17.LNK_PLACEMENT_POSITION_HKEY
    )
, PLACEMENT_RECORD_TYPE AS 
	( 
		SELECT DISTINCT
			  DVO_SRC19.PLACEMENT_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC19.LNA_PLACEMENT_RECORDTYPE_HKEY AS BASE_OBJECT_L_H_KEY
			, DVO_SRC19.RECORDTYPE_HKEY AS BASE_OBJECT_F_H_KEY
            , ROW_NUMBER() OVER (
				PARTITION BY DVO_SRC19.PLACEMENT_HKEY -- Partition by placement to get the latest company
				ORDER BY SAT_SRC1_1_19._AIRBYTE_EXTRACTED_AT DESC -- Order by snapshot timestamp to get the latest
			) AS RN
			, SAT_SRC1_1_19._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
		FROM {{ source('eli_dv_bv', 'view_lna_placement_recordtype') }} DVO_SRC19
		INNER JOIN {{ ref('view_las_bh4sf_placement_recordtype_bvv_curr') }} SAT_SRC1_1_19 ON  DVO_SRC19.LNA_PLACEMENT_RECORDTYPE_HKEY = SAT_SRC1_1_19.LNA_PLACEMENT_RECORDTYPE_HKEY
	)
SELECT DISTINCT
    UPPER(SHA2(
        UPPER(REPLACE(COALESCE(TRIM(PLACEMENTS.PLACEMENT_BK),'~'), '\#', '\\\#')) || '\#' ||
        UPPER(REPLACE(COALESCE(TRIM(TO_CHAR(PLACEMENTS.SNAPSHOT__TIMESTAMP, 'DD/MM/YYYY HH24:MI:SS')),'~'), '\#', '\\\#')) || '\#'
    )) AS DIM_PLACEMENT_HKEY
    , PLACEMENTS.BASE_OBJECT_H_KEY AS BASE_OBJECT_H_KEY
    , PLACEMENTS.PLACEMENT_BK AS PLACEMENT_BK
    , PLACEMENTS.SNAPSHOT__TIMESTAMP AS SNAPSHOT__TIMESTAMP
    , PLACEMENTS.ACTUAL_END_DATE AS ACTUAL_END_DATE
    , PLACEMENTS.AVAILABLE_FOR_REASSIGNMENT AS AVAILABLE_FOR_REASSIGNMENT
    , PLACEMENTS.DW_BH_ID AS DW_BH_ID
    , PLACEMENTS.CLOSING_REPORT_NUMBER AS CLOSING_REPORT_NUMBER
    , PLACEMENTS.CONTRACT_TYPE AS CONTRACT_TYPE
    , PLACEMENTS.CONTRACTOR_TYPE AS CONTRACTOR_TYPE
    , PLACEMENTS.DIVISION AS DIVISION
    , PLACEMENTS.DOMAIN AS DOMAIN
    , PLACEMENTS.END_ASSIGNMENT_COMMENTS AS END_ASSIGNMENT_COMMENTS
    , PLACEMENTS.END_ASSIGNMENT_REASON AS END_ASSIGNMENT_REASON
    , PLACEMENTS.ESTIMATED_END_DATE AS ESTIMATED_END_DATE
    , PLACEMENTS.HIRING_MANAGER AS HIRING_MANAGER
    , PLACEMENTS.IMMIGRATION_SPONSORSHIP AS IMMIGRATION_SPONSORSHIP
    , PLACEMENTS.IS_WORK_FROM_HOME AS IS_WORK_FROM_HOME
    , PLACEMENTS.PLACEMENT_ELI_LEGACY_SYSTEM_ID AS PLACEMENT_ELI_LEGACY_SYSTEM_ID
    , PLACEMENTS.ONBOARDING_STATUS AS ONBOARDING_STATUS
    , PLACEMENTS.PAYMENT_TERMS AS PAYMENT_TERMS
    , PLACEMENTS.SEGMENT AS SEGMENT
    , PLACEMENTS.START_DATE AS START_DATE
    , PLACEMENTS.PLACEMENT_STATUS AS PLACEMENT_STATUS
    , PLACEMENTS.PLACEMENT_VIA_SF_LEGACY_ID AS PLACEMENT_VIA_SF_LEGACY_ID
    , PLACEMENTS.WORK_LOCATION AS WORK_LOCATION
	, PLACEMENTS.ACCOUNT_LOCATION AS ACCOUNT_LOCATION
    , PLACEMENTS.CONSULTING_REVENUE AS CONSULTING_REVENUE
    , COMPANIES.ACCOUNT_NAME AS ACCOUNT_NAME
    , ASSIGNED_RECRUITERS.ASSIGNED_RECRUITER AS ASSIGNED_RECRUITER
    , CONTACTS.CONTACT_NAME AS BILLING_CONTACT
    , POSITIONS.JOB_NAME AS JOB_NAME
    , MATCHES.MATCH_NAME AS MATCH_NAME
    , JOB_OWNERS.PLACEMENT_JOB_OWNER AS PLACEMENT_JOB_OWNER
    , TIMESHEET_APPROVERS.TIMESHEET_APPROVER AS TIMESHEET_APPROVER
	, RECORD_TYPES.RECORD_TYPE AS RECORD_TYPE
    FROM PLACEMENTS PLACEMENTS -- MAIN_HUB: HUB_PLACEMENT
    --Join HUB_COMPANY to link table on Primary key HKEY to get the company name
    INNER JOIN PLACEMENT_COMPANY PLACEMENT_COMPANY ON  PLACEMENTS.BASE_OBJECT_H_KEY = PLACEMENT_COMPANY.BASE_OBJECT_H_KEY 
        AND PLACEMENT_COMPANY.RN = 1 -- Get the latest company for the placement
    INNER JOIN COMPANIES COMPANIES ON  PLACEMENT_COMPANY.BASE_OBJECT_F_H_KEY = COMPANIES.BASE_OBJECT_H_KEY
    --Join HUB_USER to link table on Primary key HKEY to get the user
    INNER JOIN PLACEMENT_AR PLACEMENT_AR ON  PLACEMENTS.BASE_OBJECT_H_KEY = PLACEMENT_AR.BASE_OBJECT_H_KEY 
        AND PLACEMENT_AR.RN = 1 -- Get the latest user for the placement
    INNER JOIN ASSIGNED_RECRUITERS ASSIGNED_RECRUITERS ON  PLACEMENT_AR.BASE_OBJECT_F_H_KEY = ASSIGNED_RECRUITERS.BASE_OBJECT_H_KEY
    --Join HUB_CONTACT to link table on Primary key HKEY to get the contact name
    INNER JOIN PLACEMENT_BILLINGCONTACT PLACEMENT_BILLINGCONTACT ON  PLACEMENTS.BASE_OBJECT_H_KEY = PLACEMENT_BILLINGCONTACT.BASE_OBJECT_H_KEY 
        AND PLACEMENT_BILLINGCONTACT.RN = 1 -- Get the latest contact for the placement
    INNER JOIN CONTACTS CONTACTS ON PLACEMENT_BILLINGCONTACT.BASE_OBJECT_F_H_KEY = CONTACTS.BASE_OBJECT_H_KEY
    --Join HUB_POSITION to link table on Primary key HKEY to get the job name
    INNER JOIN PLACEMENT_POSITION PLACEMENT_POSITION ON  PLACEMENTS.BASE_OBJECT_H_KEY = PLACEMENT_POSITION.BASE_OBJECT_H_KEY 
        AND PLACEMENT_POSITION.RN = 1 -- Get the latest position for the placement
    INNER JOIN POSITIONS POSITIONS ON PLACEMENT_POSITION.BASE_OBJECT_F_H_KEY = POSITIONS.BASE_OBJECT_H_KEY
    --Join HUB_MATCH to link table on Primary key HKEY to get the match name
    INNER JOIN PLACEMENT_MATCH PLACEMENT_MATCH ON  PLACEMENTS.BASE_OBJECT_H_KEY = PLACEMENT_MATCH.BASE_OBJECT_H_KEY 
        AND PLACEMENT_MATCH.RN = 1 -- Get the latest match for the placement
    INNER JOIN MATCHES MATCHES ON PLACEMENT_MATCH.BASE_OBJECT_F_H_KEY = MATCHES.BASE_OBJECT_H_KEY
    --Join HUB_USER to link table on Primary key HKEY to get the user name
    INNER JOIN PLACEMENT_JOBOWNER PLACEMENT_JOBOWNER ON  PLACEMENTS.BASE_OBJECT_H_KEY = PLACEMENT_JOBOWNER.BASE_OBJECT_H_KEY 
        AND PLACEMENT_JOBOWNER.RN = 1 -- Get the latest user for the placement
    INNER JOIN JOB_OWNERS JOB_OWNERS ON PLACEMENT_JOBOWNER.BASE_OBJECT_F_H_KEY = JOB_OWNERS.BASE_OBJECT_H_KEY
    --Join HUB_CONTACT to link table on Primary key HKEY to get the contact name
    INNER JOIN PLACEMENT_TIMESHEETAPPROVER PLACEMENT_TIMESHEETAPPROVER ON  PLACEMENTS.BASE_OBJECT_H_KEY = PLACEMENT_TIMESHEETAPPROVER.BASE_OBJECT_H_KEY 
		AND PLACEMENT_TIMESHEETAPPROVER.RN = 1 -- Get the latest contact for the placement
    INNER JOIN TIMESHEET_APPROVERS TIMESHEET_APPROVERS ON PLACEMENT_TIMESHEETAPPROVER.BASE_OBJECT_F_H_KEY = TIMESHEET_APPROVERS.BASE_OBJECT_H_KEY
	--Join HUB_RECORDTYPE to link table on Primary key HKEY to get the record type name
    INNER JOIN PLACEMENT_RECORD_TYPE PLACEMENT_RECORD_TYPE ON  PLACEMENTS.BASE_OBJECT_H_KEY = PLACEMENT_RECORD_TYPE.BASE_OBJECT_H_KEY 
		AND PLACEMENT_RECORD_TYPE.RN = 1 -- Get the latest record type for the placement
    INNER JOIN RECORD_TYPES RECORD_TYPES ON PLACEMENT_RECORD_TYPE.BASE_OBJECT_F_H_KEY = RECORD_TYPES.BASE_OBJECT_H_KEY